import React, { useState } from "react";
import {
  Box,
  Typography,
  Paper,
  Button,
  Grid,
  Card,
  CardContent,
  Avatar,
  Divider,
  List,
  ListItem,
  ListItemIcon,
  ListItemText,
  AppBar,
  Toolbar,
  Drawer,
  IconButton,
  useMediaQuery,
  useTheme,
} from "@mui/material";

import {
  Dashboard as DashboardIcon,
  People as PeopleIcon,
  Badge as StaffIcon,
  RestaurantMenu as MenuIcon,
  ReceiptLong as OrdersIcon,
  Inventory as InventoryIcon,
  RateReview as ReviewIcon,
  Assessment as ReportsIcon,
  Logout as LogoutIcon,
  Menu as MenuButtonIcon,
  Restaurant as RestaurantIcon,
  ShoppingCart as ShoppingCartIcon,
  CurrencyRupee as RupeeIcon,
} from "@mui/icons-material";

const drawerWidth = 240;

const AdminDashboard = ({ user, onLogout }) => {
  const theme = useTheme();

  const isMobile = useMediaQuery(
    theme.breakpoints.down("md")
  );

  const [mobileOpen, setMobileOpen] = useState(false);

  const [activePage, setActivePage] =
    useState("Dashboard");

  const handleDrawerToggle = () => {
    setMobileOpen(!mobileOpen);
  };

  const handleNavigation = (page) => {
    setActivePage(page);

    if (isMobile) {
      setMobileOpen(false);
    }
  };

  const menuItems = [
    {
      name: "Dashboard",
      icon: <DashboardIcon />,
    },
    {
      name: "Users",
      icon: <PeopleIcon />,
    },
    {
      name: "Staff",
      icon: <StaffIcon />,
    },
    {
      name: "Menu",
      icon: <MenuIcon />,
    },
    {
      name: "Orders",
      icon: <OrdersIcon />,
    },
    {
      name: "Inventory",
      icon: <InventoryIcon />,
    },
    {
      name: "Reviews",
      icon: <ReviewIcon />,
    },
    {
      name: "Reports",
      icon: <ReportsIcon />,
    },
  ];

  const drawerContent = (
    <Box
      sx={{
        height: "100%",
        display: "flex",
        flexDirection: "column",
      }}
    >
      {/* Logo */}
      <Box
        sx={{
          p: 2.5,
          display: "flex",
          alignItems: "center",
          gap: 1.5,
          background:
            "linear-gradient(135deg, #2E7D32, #4CAF50)",
          color: "white",
        }}
      >
        <RestaurantIcon
          sx={{ fontSize: 35 }}
        />

        <Box>
          <Typography
            variant="h6"
            sx={{ fontWeight: 800 }}
          >
            CanteenPro
          </Typography>

          <Typography
            variant="caption"
            sx={{ opacity: 0.9 }}
          >
            Admin Panel
          </Typography>
        </Box>
      </Box>

      {/* Navigation */}
      <List sx={{ p: 1.5, flexGrow: 1 }}>
        {menuItems.map((item) => {
          const selected =
            activePage === item.name;

          return (
            <ListItem
              key={item.name}
              disablePadding
              sx={{ mb: 0.5 }}
            >
              <Button
                fullWidth
                onClick={() =>
                  handleNavigation(item.name)
                }
                startIcon={item.icon}
                sx={{
                  justifyContent: "flex-start",
                  textTransform: "none",
                  px: 2,
                  py: 1.3,
                  borderRadius: 2,
                  color: selected
                    ? "#2E7D32"
                    : "#555",
                  backgroundColor: selected
                    ? "#E8F5E9"
                    : "transparent",
                  fontWeight: selected
                    ? 700
                    : 500,

                  "&:hover": {
                    backgroundColor:
                      "#E8F5E9",
                    color: "#2E7D32",
                  },
                }}
              >
                {item.name}
              </Button>
            </ListItem>
          );
        })}
      </List>

      <Divider />

      {/* Logout */}
      <Box sx={{ p: 2 }}>
        <Button
          fullWidth
          variant="outlined"
          color="error"
          startIcon={<LogoutIcon />}
          onClick={onLogout}
          sx={{
            textTransform: "none",
            fontWeight: 700,
            borderRadius: 2,
            py: 1.2,
          }}
        >
          Logout
        </Button>
      </Box>
    </Box>
  );

  const renderDashboard = () => {
    return (
      <>
        {/* Welcome */}
        <Paper
          sx={{
            p: 3,
            mb: 3,
            borderRadius: 3,
            background:
              "linear-gradient(135deg, #2E7D32, #4CAF50)",
            color: "white",
          }}
        >
          <Typography
            variant="h4"
            sx={{
              fontWeight: 800,
              mb: 1,
            }}
          >
            Welcome, {user.name}
          </Typography>

          <Typography
            sx={{ opacity: 0.9 }}
          >
            Manage your canteen operations
            from one place.
          </Typography>

          <Typography
            variant="body2"
            sx={{
              mt: 1,
              opacity: 0.85,
            }}
          >
            Mobile: {user.mobile}
          </Typography>
        </Paper>

        {/* Statistics */}
        <Grid
          container
          spacing={2.5}
          sx={{ mb: 3 }}
        >
          <Grid item xs={12} sm={6} lg={3}>
            <Card
              sx={{
                borderRadius: 3,
                height: "100%",
              }}
            >
              <CardContent>
                <Avatar
                  sx={{
                    bgcolor: "#E8F5E9",
                    color: "#2E7D32",
                    mb: 2,
                  }}
                >
                  <OrdersIcon />
                </Avatar>

                <Typography
                  variant="body2"
                  color="text.secondary"
                >
                  Total Orders
                </Typography>

                <Typography
                  variant="h4"
                  sx={{
                    fontWeight: 800,
                    mt: 0.5,
                  }}
                >
                  0
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} lg={3}>
            <Card
              sx={{
                borderRadius: 3,
                height: "100%",
              }}
            >
              <CardContent>
                <Avatar
                  sx={{
                    bgcolor: "#FFF3E0",
                    color: "#EF6C00",
                    mb: 2,
                  }}
                >
                  <RupeeIcon />
                </Avatar>

                <Typography
                  variant="body2"
                  color="text.secondary"
                >
                  Revenue
                </Typography>

                <Typography
                  variant="h4"
                  sx={{
                    fontWeight: 800,
                    mt: 0.5,
                  }}
                >
                  ₹0
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} lg={3}>
            <Card
              sx={{
                borderRadius: 3,
                height: "100%",
              }}
            >
              <CardContent>
                <Avatar
                  sx={{
                    bgcolor: "#E3F2FD",
                    color: "#1976D2",
                    mb: 2,
                  }}
                >
                  <PeopleIcon />
                </Avatar>

                <Typography
                  variant="body2"
                  color="text.secondary"
                >
                  Users
                </Typography>

                <Typography
                  variant="h4"
                  sx={{
                    fontWeight: 800,
                    mt: 0.5,
                  }}
                >
                  0
                </Typography>
              </CardContent>
            </Card>
          </Grid>

          <Grid item xs={12} sm={6} lg={3}>
            <Card
              sx={{
                borderRadius: 3,
                height: "100%",
              }}
            >
              <CardContent>
                <Avatar
                  sx={{
                    bgcolor: "#F3E5F5",
                    color: "#7B1FA2",
                    mb: 2,
                  }}
                >
                  <StaffIcon />
                </Avatar>

                <Typography
                  variant="body2"
                  color="text.secondary"
                >
                  Staff
                </Typography>

                <Typography
                  variant="h4"
                  sx={{
                    fontWeight: 800,
                    mt: 0.5,
                  }}
                >
                  0
                </Typography>
              </CardContent>
            </Card>
          </Grid>
        </Grid>

        {/* Recent Orders */}
        <Paper
          sx={{
            p: 3,
            borderRadius: 3,
          }}
        >
          <Box
            sx={{
              display: "flex",
              alignItems: "center",
              gap: 1,
              mb: 1,
            }}
          >
            <ShoppingCartIcon
              sx={{ color: "#2E7D32" }}
            />

            <Typography
              variant="h6"
              sx={{ fontWeight: 700 }}
            >
              Recent Orders
            </Typography>
          </Box>

          <Divider sx={{ my: 2 }} />

          <Box
            sx={{
              textAlign: "center",
              py: 5,
            }}
          >
            <OrdersIcon
              sx={{
                fontSize: 55,
                color: "#BDBDBD",
                mb: 1,
              }}
            />

            <Typography
              variant="h6"
              color="text.secondary"
            >
              No orders yet
            </Typography>

            <Typography
              variant="body2"
              color="text.secondary"
              sx={{ mt: 1 }}
            >
              Order data will appear here
              once customers place orders.
            </Typography>
          </Box>
        </Paper>
      </>
    );
  };

  const renderComingSoon = () => {
    const currentItem = menuItems.find(
      (item) => item.name === activePage
    );

    return (
      <Paper
        sx={{
          p: 5,
          borderRadius: 3,
          textAlign: "center",
        }}
      >
        <Box
          sx={{
            width: 80,
            height: 80,
            borderRadius: "50%",
            backgroundColor: "#E8F5E9",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            mx: "auto",
            mb: 2,
            color: "#2E7D32",
          }}
        >
          {currentItem?.icon}
        </Box>

        <Typography
          variant="h4"
          sx={{
            fontWeight: 800,
            color: "#2E7D32",
          }}
        >
          {activePage}
        </Typography>

        <Typography
          color="text.secondary"
          sx={{
            mt: 1,
            maxWidth: 500,
            mx: "auto",
          }}
        >
          {activePage} management will be
          connected to the database in the
          next development step.
        </Typography>

        <Typography
          variant="body2"
          color="text.secondary"
          sx={{ mt: 2 }}
        >
          This navigation is ready. We will
          implement the actual functionality
          one module at a time.
        </Typography>
      </Paper>
    );
  };

  return (
    <Box
      sx={{
        display: "flex",
        minHeight: "100vh",
        backgroundColor: "#F5F7F5",
      }}
    >
      {/* Desktop Drawer */}
      {!isMobile && (
        <Drawer
          variant="permanent"
          sx={{
            width: drawerWidth,
            flexShrink: 0,

            "& .MuiDrawer-paper": {
              width: drawerWidth,
              boxSizing: "border-box",
              borderRight:
                "1px solid #E0E0E0",
            },
          }}
        >
          {drawerContent}
        </Drawer>
      )}

      {/* Mobile Drawer */}
      {isMobile && (
        <Drawer
          variant="temporary"
          open={mobileOpen}
          onClose={handleDrawerToggle}
          ModalProps={{
            keepMounted: true,
          }}
          sx={{
            "& .MuiDrawer-paper": {
              width: drawerWidth,
            },
          }}
        >
          {drawerContent}
        </Drawer>
      )}

      {/* Main Content */}
      <Box
        sx={{
          flexGrow: 1,
          minWidth: 0,
        }}
      >
        {/* Top Bar */}
        <AppBar
          position="sticky"
          elevation={0}
          sx={{
            backgroundColor: "white",
            color: "#222",
            borderBottom:
              "1px solid #E0E0E0",
          }}
        >
          <Toolbar>
            {isMobile && (
              <IconButton
                edge="start"
                onClick={handleDrawerToggle}
                sx={{ mr: 2 }}
              >
                <MenuButtonIcon />
              </IconButton>
            )}

            <Typography
              variant="h6"
              sx={{
                fontWeight: 800,
                color: "#2E7D32",
                flexGrow: 1,
              }}
            >
              {activePage}
            </Typography>

            <Box
              sx={{
                display: "flex",
                alignItems: "center",
                gap: 1.5,
              }}
            >
              <Avatar
                sx={{
                  width: 38,
                  height: 38,
                  bgcolor: "#2E7D32",
                  fontWeight: 700,
                }}
              >
                {user.name
                  ? user.name
                      .charAt(0)
                      .toUpperCase()
                  : "A"}
              </Avatar>

              {!isMobile && (
                <Box>
                  <Typography
                    variant="body2"
                    sx={{ fontWeight: 700 }}
                  >
                    {user.name}
                  </Typography>

                  <Typography
                    variant="caption"
                    color="text.secondary"
                  >
                    Administrator
                  </Typography>
                </Box>
              )}
            </Box>
          </Toolbar>
        </AppBar>

        {/* Page */}
        <Box
          sx={{
            p: {
              xs: 2,
              sm: 3,
              md: 4,
            },
          }}
        >
          {activePage === "Dashboard"
            ? renderDashboard()
            : renderComingSoon()}
        </Box>
      </Box>
    </Box>
  );
};

export default AdminDashboard;
